-- Gold Query
SELECT DISTINCT t1.player_name FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id ORDER BY t2.potential DESC, t1.player_name NULLS LAST LIMIT 1;

/*
Gold Result:
('Christopher Bernard',)
*/

-- Prediction Query
SELECT "player"."player_name" FROM "player" INNER JOIN "player_attributes" ON "player"."player_api_id" = "player_attributes"."player_api_id" WHERE "player_attributes"."potential" = (SELECT MAX("potential") FROM "player_attributes");

/*
Prediction Result:
('Christopher Bernard',)
('Christopher Bernard',)
